//! The glyph names of the PDF's base encodings, by code: what a renderer looks a simple
//! font's glyph up by when the font names an encoding and its `/Differences` don't cover the
//! code. LimarePDF's text reading goes by characters (lopdf's tables); writing new text in a
//! font's own program (`own_font.rs`) must find the glyph the renderer will draw, which goes
//! by these names.
//!
//! The WinAnsi and MacRoman tables are generated by `tools/gen_base_encodings.py` (fontTools'
//! Mac OS Roman names and the Adobe Glyph List for New Fonts over Windows-1252), named as the
//! PDF readers name them (PDFBox, and hayro after it): 0xA0 nbspace, 0xAD sfthyphen; WinAnsi's
//! unused codes past 40 are bullets. StandardEncoding is read-fonts'. MacExpertEncoding,
//! for expert fonts (small capitals, old-style figures), isn't read: its codes find no glyph.

use skrifa::raw::ps::encoding::PredefinedEncoding;

/// A simple font's base encoding: the one its `/Encoding` (or the `/BaseEncoding` of an
/// encoding dictionary) names, else the program's own (`BuiltIn`).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) enum Base {
    Standard,
    WinAnsi,
    MacRoman,
    MacExpert,
    BuiltIn,
}

impl Base {
    /// The base encoding named `name`; an unknown name is the program's own.
    pub(crate) fn named(name: &[u8]) -> Self {
        match name {
            b"StandardEncoding" => Self::Standard,
            b"WinAnsiEncoding" => Self::WinAnsi,
            b"MacRomanEncoding" => Self::MacRoman,
            b"MacExpertEncoding" => Self::MacExpert,
            _ => Self::BuiltIn,
        }
    }

    /// The glyph name `code` stands for in this encoding, as renderers read it: `.notdef`
    /// for code 0, MacRoman with Mac OS Roman's codes after it. `None` for the program's own
    /// encoding, which has no names here, and for MacExpert.
    pub(crate) fn name(self, code: u8) -> Option<&'static str> {
        if code == 0 {
            return Some(".notdef");
        }
        let some = |n: &'static str| (!n.is_empty()).then_some(n);
        match self {
            Self::Standard => {
                Some(PredefinedEncoding::Standard.name(code)).filter(|n| *n != ".notdef")
            }
            Self::WinAnsi => some(WIN_ANSI[code as usize]).or((code > 40).then_some("bullet")),
            Self::MacRoman => some(MAC_ROMAN[code as usize]).or_else(|| {
                (MAC_OS_ROMAN.iter())
                    .find(|(c, _)| *c == code)
                    .map(|(_, n)| *n)
            }),
            Self::MacExpert | Self::BuiltIn => None,
        }
    }
}

/// The code glyph `name` has in Mac OS Roman, else in MacRomanEncoding: how a TrueType font's
/// (1,0) cmap is looked up for a named glyph.
pub(crate) fn mac_code(name: &str) -> Option<u8> {
    (MAC_OS_ROMAN.iter())
        .find(|(_, n)| *n == name)
        .map(|(c, _)| *c)
        .or_else(|| {
            (MAC_ROMAN.iter())
                .position(|n| !n.is_empty() && *n == name)
                .map(|c| c as u8)
        })
}

