/// The codes Mac OS Roman adds to MacRomanEncoding, with their glyphs.
const MAC_OS_ROMAN: [(u8, &str); 16] = [
    (0xAD, "notequal"),
    (0xB0, "infinity"),
    (0xB2, "lessequal"),
    (0xB3, "greaterequal"),
    (0xB6, "partialdiff"),
    (0xB7, "summation"),
    (0xB8, "product"),
    (0xB9, "pi"),
    (0xBA, "integral"),
    (0xBD, "Omega"),
    (0xC3, "radical"),
    (0xC5, "approxequal"),
    (0xC6, "Delta"),
    (0xD7, "lozenge"),
    (0xDB, "Euro"),
    (0xF0, "apple"),
];

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn base_encodings_name_their_glyphs_as_the_readers_do() {
        assert_eq!(Base::WinAnsi.name(b'a'), Some("a"));
        assert_eq!(Base::WinAnsi.name(0xA0), Some("nbspace"));
        assert_eq!(Base::WinAnsi.name(0x81), Some("bullet"));
        assert_eq!(Base::WinAnsi.name(0x1F), None);
        assert_eq!(Base::WinAnsi.name(0), Some(".notdef"));
        assert_eq!(Base::Standard.name(0xAE), Some("fi"));
        assert_eq!(Base::Standard.name(0x7F), None);
        assert_eq!(Base::MacRoman.name(0xDB), Some("currency"));
        assert_eq!(Base::MacRoman.name(0xB0), Some("infinity"));
        assert_eq!(Base::BuiltIn.name(b'a'), None);
        assert_eq!(mac_code("Euro"), Some(0xDB));
        assert_eq!(mac_code("currency"), Some(0xDB));
        assert_eq!(mac_code("a"), Some(b'a'));
        assert_eq!(mac_code("nosuchglyph"), None);
    }
}
